<?php use App\Core\Security;use App\Support\Jalali;use App\Core\Auth;use App\Services\PermissionService;?><div class="table-wrap"><table class="table table-bordered table-hover align-middle"><thead><tr><th>کد کالا</th><th>نام کالا</th><th>قیمت‌های سه منبع</th><th>واحد</th><th>تاریخ ثبت</th><th>آخرین دریافت</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody><?php if(!$products):?><tr><td colspan="8" class="text-center">رکوردی یافت نشد.</td></tr><?php endif;foreach($products as $p):$latest=$p['latest_price_date'];$days=$latest?max(0,(int)((time()-strtotime($latest))/86400)):999;$cls=$days<7?'status-green':($days<=10?'status-orange':'status-red');?><tr class="<?=$cls?>"><td><?=Security::e($p['product_code'])?></td><td><?=Security::e($p['product_name'])?></td><td><?php foreach(($prices[$p['id']]??[]) as $pr):?><div>منبع <?=(int)$pr['source_no']?>: <?=Security::e($pr['supplier'])?> | بسته <?=number_format((float)$pr['package_price'],2)?> | واحد <?=number_format((float)$pr['unit_price'],2)?> | <?=Security::e(Jalali::fromGregorian($pr['price_received_at']))?></div><?php endforeach;?></td><td><?=Security::e($p['unit_name'])?></td><td><?=Security::e(Jalali::fromGregorian($p['registered_at']))?></td><td><?=$latest?Security::e(Jalali::fromGregorian($latest)):'—'?></td><td><?=$days<7?'':($days<=10?'جهت بازبینی':'رصد کنید')?></td><td class="text-nowrap"><?php if(PermissionService::allows(Auth::userId(),'prices.edit')):?><a class="btn btn-sm btn-outline-primary" href="/pricing/public/prices/<?=(int)$p['id']?>/edit">ویرایش</a><?php endif;if(PermissionService::allows(Auth::userId(),'prices.delete')):?><form method="post" action="/pricing/public/prices/<?=(int)$p['id']?>/delete" class="d-inline" onsubmit="return confirm('حذف شود؟')"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><button class="btn btn-sm btn-outline-danger">حذف</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>